import heapq

def match(orders):
    buy_heap = []   # (-price, seq, id)
    sell_heap = []  # (price, seq, id)
    orders_info = {}  # id -> dict with side, price, qty, active
    seq_counter = 0
    trades = []

    def clean_buy():
        while buy_heap and (buy_heap[0][2] not in orders_info
                             or not orders_info[buy_heap[0][2]]['active']
                             or orders_info[buy_heap[0][2]]['qty'] <= 0):
            heapq.heappop(buy_heap)

    def clean_sell():
        while sell_heap and (sell_heap[0][2] not in orders_info
                              or not orders_info[sell_heap[0][2]]['active']
                              or orders_info[sell_heap[0][2]]['qty'] <= 0):
            heapq.heappop(sell_heap)

    for order in orders:
        typ = order[0]

        if typ == 'cancel':
            oid = order[1]
            if oid in orders_info:
                orders_info[oid]['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        seq = seq_counter
        seq_counter += 1
        remaining = qty

        if side == 'buy':
            clean_sell()
            while remaining > 0 and sell_heap:
                top_price, top_seq, top_id = sell_heap[0]
                if typ != 'market' and price < top_price:
                    break
                info = orders_info[top_id]
                trade_qty = min(remaining, info['qty'])
                trades.append([oid, top_id, top_price, trade_qty])
                remaining -= trade_qty
                info['qty'] -= trade_qty
                if info['qty'] == 0:
                    info['active'] = False
                    heapq.heappop(sell_heap)
                clean_sell()

            if typ == 'limit':
                if remaining > 0:
                    orders_info[oid] = {'side': 'buy', 'price': price, 'qty': remaining, 'active': True}
                    heapq.heappush(buy_heap, (-price, seq, oid))
                else:
                    orders_info[oid] = {'side': 'buy', 'price': price, 'qty': 0, 'active': False}
        else:  # sell
            clean_buy()
            while remaining > 0 and buy_heap:
                neg_price, top_seq, top_id = buy_heap[0]
                top_price = -neg_price
                if typ != 'market' and price > top_price:
                    break
                info = orders_info[top_id]
                trade_qty = min(remaining, info['qty'])
                trades.append([top_id, oid, top_price, trade_qty])
                remaining -= trade_qty
                info['qty'] -= trade_qty
                if info['qty'] == 0:
                    info['active'] = False
                    heapq.heappop(buy_heap)
                clean_buy()

            if typ == 'limit':
                if remaining > 0:
                    orders_info[oid] = {'side': 'sell', 'price': price, 'qty': remaining, 'active': True}
                    heapq.heappush(sell_heap, (price, seq, oid))
                else:
                    orders_info[oid] = {'side': 'sell', 'price': price, 'qty': 0, 'active': False}

    return trades

